out vec4 fragColor;

uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Audio Reactive Uniforms
uniform float u_bass;
uniform float u_mid;
uniform float u_treble;
uniform float u_vol;

// Custom Parameters
uniform float u_speed;
uniform float u_density;
uniform float u_tail_length;
uniform float u_glow_intensity;
uniform float u_color_shift;
uniform float u_nexus_warp;
uniform float u_radiance_bloom;

// Pseudo-random hash function
float hash11(float p) {
    p = fract(p * .1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}

// 2D Rotation matrix
mat2 rot2D(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// Rainbow palette function with shift
vec3 getRainbow(float t) {
    vec3 c = 0.5 + 0.5 * cos(6.28318 * (vec3(1.0, 0.66, 0.33) + t + u_color_shift));
    return c;
}

void main() {
    // Correct UVs with aspect ratio
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;

    // NAKED NEXUS WARP: Convert UVs to polar-like or warped space
    float r = length(uv);
    float angle_polar = atan(uv.y, uv.x);

    // Twist the space based on radius and time
    float twist = sin(r * 2.0 - iTime * 0.5) * u_nexus_warp;
    uv *= rot2D(twist + u_bass * 0.2);

    // Grid System (Radiant Nexus Columns)
    // Scale UV.x by density to create vertical columns emanating from center
    float density = u_density * 20.0;
    float col_id = floor(uv.x * density);
    float col_uv = fract(uv.x * density) - 0.5;

    // Random values per column
    float h = hash11(col_id);

    // Falling animation logic
    // Add audio reactivity to speed
    float speed = (u_speed * 1.2) + (u_bass * 0.6);
    float time = iTime * speed + (h * 100.0);

    // Accumulate color
    vec3 finalColor = vec3(0.0);

    // Draw multiple layers of radiant stars for depth
    for(float i = 0.0; i < 3.0; i++) {
        float layer_h = hash11(col_id + i * 13.45);
        float layer_speed = speed * (0.6 + i * 0.3);

        // Vertical position logic with nexus influence
        float y_pos = fract(uv.y * (0.4 + i * 0.15) - iTime * layer_speed - layer_h);

        // Horizontal distance to column center
        float x_dist = abs(col_uv);

        // Intensity based on vertical distance (the tail)
        // Adjust tail length by parameter
        float tail_fade = pow(y_pos, 5.0 / (u_tail_length + 0.01));

        // Horizontal sharpness of the light beam
        float beam = smoothstep(0.12, 0.0, x_dist * (12.0 + i * 6.0));

        // Color for this specific star nexus
        vec3 starCol = getRainbow(layer_h + iTime * 0.05 + i * 0.1);

        // Audio reaction: Stars pulse with treble and mid-range
        starCol *= (1.0 + u_treble * 1.5 + u_mid * 0.5);

        // Main beam intensity
        float intensity = tail_fade * beam;

        // Add a bright "spark" or "nexus core" at the head
        float head_dist = distance(vec2(col_uv, y_pos), vec2(0.0, 0.02));
        float head = smoothstep(0.06, 0.0, head_dist);
        intensity += head * 3.0;

        // Radiance/Glow
        float glow = 0.015 / (x_dist + 0.015);
        glow *= tail_fade;

        // Core Bloom
        float bloom = 0.02 / (head_dist + 0.01);

        finalColor += starCol * (intensity + (glow + bloom) * u_glow_intensity * u_radiance_bloom * 0.2);
    }

    // Central Radiant Nexus Core
    float center_glow = 0.05 / (length(uv) + 0.05);
    finalColor += getRainbow(u_color_shift) * center_glow * (u_bass + 0.2) * u_radiance_bloom;

    // Background Atmosphere
    // Vignette and nexus depth
    float vignette = 1.0 - length(uv * 0.6);
    finalColor += vec3(0.01, 0.01, 0.03) * vignette;

    // Tone mapping (Exposure)
    finalColor = 1.0 - exp(-finalColor * 1.8);

    // Gamma correction
    finalColor = pow(finalColor, vec3(0.4545));

    fragColor = vec4(finalColor, 1.0);
}
